mapper.select:
WITH RECURSIVE redirects(source_id,target_id) AS ( SELECT source_id,target_id FROM food_merge_receipt WHERE user_id=#{_userId,jdbcType=BIGINT} UNION ALL SELECT source_id,target_id FROM food_item_move_receipt WHERE user_id=#{_userId,jdbcType=BIGINT} AND source_removed ), destinations(request_id, current_id) AS ( SELECT request_id, target_id FROM food_merge_receipt WHERE user_id=#{_userId,jdbcType=BIGINT} UNION SELECT d.request_id, r.target_id FROM destinations d JOIN redirects r ON r.source_id=d.current_id ), events AS ( SELECT h.history_id, h.food_id, COALESCE(h.recorded_food_name,m.food_name) AS food_name, h.action_type, h.previous_storage_type, h.new_storage_type, h.quantity_text, h.created_at, h.changes_text, m.master_id AS current_master_id, m.food_name AS current_food_name, linked.source_name AS merged_from_name, linked.target_name AS merged_into_name, NULL::integer AS merged_item_count, EXISTS(SELECT 1 FROM food_item_move_receipt mr WHERE mr.user_id=#{_userId,jdbcType=BIGINT} AND mr.food_id=h.food_id) AS item_moved, h.after_quantity_amount, linked.target_id AS merged_target_id, h.cooking_id, 0 AS event_order, h.history_id::text AS event_key FROM food_history h JOIN food_item f ON f.food_id = h.food_id JOIN food_master m ON m.master_id=f.master_id AND m.user_id=#{_userId,jdbcType=BIGINT} LEFT JOIN food_item_move_receipt linked ON h.action_type='MERGE' AND linked.user_id=h.user_id AND linked.food_id=h.food_id AND linked.request_id=h.operation_id WHERE h.action_type NOT IN ('SPLIT_IN','COOK_IN','COOK_OUT') UNION ALL SELECT NULL::bigint, NULL::bigint, r.source_name, NULL::varchar, NULL::varchar, NULL::varchar, NULL::varchar, r.created_at, '음식명: ' || r.source_name || ' (#' || r.source_id || ') → ' || r.target_name || ' (#' || r.target_id || ')' AS changes_text, m.master_id, m.food_name, r.source_name, r.target_name, r.item_count, FALSE, NULL::numeric, r.target_id, NULL::uuid, 1, r.request_id::text FROM food_merge_receipt r LEFT JOIN ( SELECT d.request_id, m.master_id, m.food_name FROM destinations d JOIN food_master m ON m.master_id=d.current_id AND m.user_id=#{_userId,jdbcType=BIGINT} ) m ON m.request_id=r.request_id WHERE r.user_id=#{_userId,jdbcType=BIGINT} UNION ALL SELECT NULL::bigint, r.food_id, r.source_name, NULL::varchar, NULL::varchar, NULL::varchar, NULL::varchar, r.created_at, '음식명: ' || r.source_name || ' (#' || r.source_id || ') → ' || r.target_name || ' (#' || r.target_id || ')' AS changes_text, m.master_id, m.food_name, r.source_name, r.target_name, NULL::integer, TRUE, NULL::numeric, r.target_id, NULL::uuid, 2, r.request_id::text FROM food_item_move_receipt r JOIN food_item f ON f.food_id=r.food_id JOIN food_master m ON m.master_id=f.master_id AND m.user_id=#{_userId,jdbcType=BIGINT} WHERE NOT EXISTS (SELECT 1 FROM food_history recorded WHERE recorded.user_id=r.user_id AND recorded.food_id=r.food_id AND recorded.operation_id=r.request_id AND recorded.action_type='MERGE') UNION ALL SELECT NULL::bigint,c.result_food_id,c.food_name,'COOK_IN',NULL::varchar,NULL::varchar, trim_scale(c.original_quantity_amount)::text || c.quantity_unit,c.created_at, '수량: ' || trim_scale(c.original_quantity_amount)::text || c.quantity_unit || E'\n사용 재료: ' || (SELECT string_agg(ci.food_name || ' ' || trim_scale(ci.original_used_amount)::text || ci.quantity_unit, ', ' ORDER BY ci.food_id) FROM cooking_ingredient ci WHERE ci.user_id=c.user_id AND ci.cooking_id=c.cooking_id) || E'\n조리일: ' || c.cooked_at::text, NULL::bigint,NULL::varchar,NULL::varchar,NULL::varchar,NULL::integer,FALSE,c.original_quantity_amount,NULL::bigint,c.cooking_id,0,c.cooking_id::text FROM cooking_record c WHERE c.user_id=#{_userId,jdbcType=BIGINT} AND c.result_food_id IS NOT NULL ) SELECT history_id, food_id, food_name, action_type, previous_storage_type, new_storage_type, quantity_text, created_at, changes_text, current_master_id, current_food_name, merged_from_name, merged_into_name, merged_item_count, item_moved, after_quantity_amount, merged_target_id, cooking_id FROM events
AND (strpos(lower(food_name), lower(#{query})) > 0 OR strpos(lower(current_food_name), lower(#{query})) > 0 OR strpos(lower(merged_into_name), lower(#{query})) > 0 OR EXISTS(SELECT 1 FROM cooking_ingredient ci WHERE ci.user_id=#{_userId,jdbcType=BIGINT} AND ci.cooking_id=events.cooking_id AND strpos(lower(ci.food_name),lower(#{query})) > 0))
AND created_at >= #{from} AND created_at < #{until}
ORDER BY created_at DESC, event_order DESC, history_id DESC NULLS LAST, event_key DESC LIMIT #{limit}
